    def canTraverseAllPairs(self, nums: List[int]) -> bool:
        # Create a graph where each node is a number and edges exist if gcd > 1
        graph = defaultdict(list)
        max_num = max(nums)

        # Build the graph using a sieve-like approach to find common divisors
        for i in range(2, max_num + 1):
            for num in range(i, max_num + 1, i):
                if num in nums:
                    for other in range(num, max_num + 1, num):
                        if other in nums and num != other:
                            graph[num].append(other)
                            graph[other].append(num)

        # Use DFS to check if all nodes are connected
        def dfs(node, visited):
            stack = [node]
            while stack:
                current = stack.pop()
                for neighbor in graph[current]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        stack.append(neighbor)

        # Start DFS from the first number in nums
        visited = set()
        start_node = nums[0]
        dfs(start_node, visited)

        # Check if all numbers are visited
        return len(visited) == len(nums)

