                        if sorted_keys[k + 1] - sorted_keys[k] > 1:
                            imbalance += 1
                total += imbalance
        return total

class Solution:
    def longestString(self, x: int, y: int, z: int) -> int:
        # The maximum possible length of the new string is the sum of the lengths of all chosen strings
        # Since "AAA" and "BBB" are not allowed, we can't use more than 2 consecutive "AA" or "BB"
        # So, we can use at most min(x, y) * 2 + z "AA" or "BB" and z "AB"
        # The remaining "AA" or "BB" can be added at the end of the string
        return min(x, y) * 2 * 2 + z * 3 + max(x, y) - min(x, y)

class Solution:
    def minimizeConcatenatedLength(self, words: List[str]) -> int:
        n = len(words)
        dp = [[0] * n for _ in range(n)]

        for gap in range(1, n):
            for i in range(n - gap):
                j = i + gap
                dp[i][j] = float('inf')
                for k in range(i, j):
                    cost = dp[i][k] + dp[k + 1][j]
                    if words[k][-1] == words[k + 1][0]:
                        cost -= 1
                    dp[i][j] = min(dp[i][j], cost)

        return dp[0][n - 1] + len(words[0])
